import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Variant1 {
    static int countDistinct(int[] array, int start, int end) {
        boolean[] seen = new boolean[24];
        int total = 0;
        for (int i = start; i <= end; i++) {
            int c = array[i];
            if (!seen[c]) {
                seen[c] = true;
                total++;
            }
        }
        return total;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        int a = Integer.parseInt(tokenizer.nextToken());
        int b = Integer.parseInt(tokenizer.nextToken());
        int l = Integer.parseInt(tokenizer.nextToken()) - 1;
        int r = Integer.parseInt(tokenizer.nextToken()) - 1;

        int totalAB = a + b;
        int repetitions = 4;
        int[] cc = new int[totalAB * repetitions];

        int blockIndex = l / totalAB;
        l -= blockIndex * totalAB;
        r -= blockIndex * totalAB;

        int blockCount = (r - l + 1) / totalAB;
        if (blockCount > 2) {
            r -= (blockCount - 2) * totalAB;
        }

        int diff = a > b ? a - b : 1;
        for (int h = 0; h < repetitions; h++) {
            for (int k = 0; k < a - diff; k++)
                cc[(a + b) * h + k] = k;
            for (int k = 0; k < diff; k++)
                cc[(a + b) * h + a - diff + k] = (h % 2 == 0) ? a - diff + k : a + k;
        }

        int minCount = a + a;
        for (int k0 = 1; k0 <= diff; k0++) {
            for (int k = 0; k < b; k++)
                cc[(a + b) * 0 + a + k] = cc[(a + b) * 0 + a - k0];
            for (int k1 = 1; k1 <= diff; k1++) {
                for (int k = 0; k < b; k++)
                    cc[(a + b) * 1 + a + k] = cc[(a + b) * 1 + a - k1];
                for (int k2 = 1; k2 <= diff; k2++) {
                    for (int k = 0; k < b; k++)
                        cc[(a + b) * 2 + a + k] = cc[(a + b) * 2 + a - k2];
                    for (int k3 = 1; k3 <= diff; k3++) {
                        for (int k = 0; k < b; k++)
                            cc[(a + b) * 3 + a + k] = cc[(a + b) * 3 + a - k3];
                        minCount = Math.min(minCount, countDistinct(cc, l, r));
                    }
                }
            }
        }
        System.out.println(minCount);
    }
}
